class Solution:
    def numPairsDivisibleBy60(self, time: list[int]) -> int:
        count = [0] * 60
        pairs = 0
        for t in time:
            r = t % 60
            complement = (60 - r) % 60
            pairs += count[complement]
            count[r] += 1
        return pairs

